window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-df778de938dfea43"]={"versions": [{"id": "FIG-df778de938dfea43", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Domänenspezifisches Wertebereichs- und Schnittstellen-Mapping-Diagramm (Semantisches Wertebereichsprofil / Range &amp; Boundary Model) für Kurbelwellen-Drehmomentschnittstellen.\n</li><li><strong>Technischer Zweck:</strong> Standardisierung der Drehmoment-Koordination (<em>Torque Coordination</em>) zwischen Motorsteuergerät (Engine Management System, EMS) und aggregierten Antriebsstrang-/Fahrwerk-Steuergeräten (Transmission Control, ESP/ASR).\n</li><li><strong>Funktionale Einordnung:</strong> Definiert die AUTOSAR Sender-Receiver-Schnittstellenelemente (<code>AUTOSAR_EXP_AIPowertrain</code>) bezüglich ihrer physikalischen Wirkpfade (Luftpfad/langsam vs. Zündpfad/schnell), ihrer Begrenzungsebenen (Schleppmoment, Leerlaufbasis, Teillast, thermodynamisches Optimum, Motorschutz) sowie ihrer Einbettung in den Wertebereich des AUTOSAR-Datentyps.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind standardisierte AUTOSAR Application Data Elements (Einheit: Nm, Kurbelwellenreferenz) und deren relationale Ordnung entlang der Drehmomentachse:</p>\n<h5 class=\"fig-section-h5\">Datentypgrenzen &amp; Maximalpotential</h5>\n<ul class=\"fig-list\"><li><strong><code>Upper limit of data type</code> / <code>Lower limit of data type</code>:</strong> Numerische Sättigungsgrenzen des zugrundeliegenden AUTOSAR Implementation Data Types (z. B. vorzeichenbehafteter Festkomma- oder Fließkommatyp).\n</li><li><strong><code>EngTqCrksftMaxOptmCdn</code>:</strong> Maximales Kurbelwellenmoment unter thermodynamischen Idealbedingungen (Referenz-Vollastpotential bei optimalem Zündwinkel, optimalem $\\lambda$, Nenntemperatur).\n</li><li><strong><code>EngTqCrksftMax</code>:</strong> Maximales Kurbelwellenmoment bei maximaler Füllung (Luftmasse) und aktueller Motordrehzahl über den langsamen Pfad.\n</li><li><strong><code>EngTqCrksftMaxProtn</code>:</strong> Dynamische Obergrenze zum Bauteilschutz (Engine Protection Interventionsgrenze; limitiert alle Sollwerte bei thermischer/mechanischer Überlast).\n</li></ul>\n<h5 class=\"fig-section-h5\">Schneller Eingriffspfad &amp; Ist-Zustand (Dynamischer Bereich)</h5>\n<ul class=\"fig-list\"><li><strong><code>EngTqCrksftMaxFast</code>:</strong> Maximal erreichbares Drehmoment über den schnellen Pfad bei aktueller Zylinderfüllung (optimaler Zündwinkel, ungedrosselter Wirkungsgrad). Dient externen Systemen als oberer transienter Stellgrenzwert (<code>Setpoint</code>).\n</li><li><strong><code>EngTqCrksft</code>:</strong> Aktuell an der Kurbelwelle anliegendes Ist-Drehmoment; resultiert aus der aktuellen Zylinderfüllung abzüglich Zündwinkelspätverstellung (<code>spark retard</code>), Gemischadaption ($\\lambda$) und internen Reibverlusten.\n</li><li><strong><code>EngTqCrksftMinFast</code>:</strong> Minimal erreichbares Drehmoment über den schnellen Pfad bei maximaler Zündwinkelspätverstellung (<code>Maximum spark retard</code>) ohne Zylinderausblendung. Dient externen Systemen als unterer transienter Stellgrenzwert (<code>Setpoint</code>).\n</li></ul>\n<h5 class=\"fig-section-h5\">Schleppmoment- und Basispfad (Langsamer Pfad / Schub)</h5>\n<ul class=\"fig-list\"><li><strong><code>EngTqCrksftMinBasc</code>:</strong> Minimales Kurbelwellendrehmoment realisiert über den langsamen Pfad bei minimaler Füllung (geschlossene Drosselklappe/Minimalhub) und Basiszündwinkel (ohne Spätverstellung).\n</li><li><strong><code>EngTqCrksftMinWoCutOff</code>:</strong> Minimales Drehmoment über kombinierten langsamen und schnellen Pfad ohne Schubabschaltung (minimale Füllung + maximale Spätzündung).\n</li><li><strong><code>EngTqCrksftMin</code>:</strong> Absolutes Minimalmoment an der Kurbelwelle unter Berücksichtigung aller innermotorischen Verluste (Reibung, Ladungswechsel, Nebenaggregate; entspricht Schubabschaltung / indiziertes Moment ≈ 0).\n</li><li><strong><code>Indicated torque</code>:</strong> Verbrennungsmoment vor Abzug der innermotorischen Reib- und Ladungswechselverluste (Nullpunktverschiebung gegenüber dem Kurbelwellen-Nettomoment).\n</li></ul>\n<h5 class=\"fig-section-h5\">Momentenreserve-Schnittstellen (<code>Additional interfaces</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>PtTqResvEng</code>:</strong> Drehmomentreserve-Anforderung vom Powertrain/Getriebe an den Motor (Öffnen der Drosselklappe / Vorsteuerung des Füllungspfads).\n</li><li><strong><code>EngTqResvPt</code>:</strong> Rückmeldung des Motors über die aktuell vorgehaltene und schnell aktivierbare Drehmomentreserve an den Powertrain.\n</li></ul>\n<h5 class=\"fig-section-h5\">Mathematische Ordnungshierarchie</h5>\n<p class=\"fig-p\">$$\\text{Lower Limit} \\le \\text{EngTqCrksftMin} &lt; \\text{EngTqCrksftMinWoCutOff} &lt; \\text{EngTqCrksftMinBasc} \\le 0 \\le \\text{EngTqCrksftMinFast} \\le \\text{EngTqCrksft} \\le \\text{EngTqCrksftMaxFast} \\le \\text{EngTqCrksftMax} \\le \\text{EngTqCrksftMaxOptmCdn} \\le \\text{Upper Limit}$$</p>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Pfadentkopplung (Dual-Path-Architektur):</strong>\n<ul class=\"fig-list\"><li><em>Slow Path (Luftpfad, $\\tau \\approx 100\\dots 300\\,\\text{ms}$):</em> Definiert das Grundfüllungsband zwischen <code>EngTqCrksftMinBasc</code> und <code>EngTqCrksftMax</code>.\n</li><li><em>Fast Path (Zünd-/Einspritzpfad, zylindertakt-synchron, $\\tau \\approx 10\\dots 30\\,\\text{ms}$):</em> Arbeitet innerhalb des Füllungskorridors [<code>EngTqCrksftMinFast</code>, <code>EngTqCrksftMaxFast</code>].\n</li></ul>\n</li><li><strong>Sollwert-Intervention (<code>Setpoint</code>):</strong>\n<ul class=\"fig-list\"><li>Externe Drehmomenteingriffe (z. B. Getriebeeingriff während der Schaltphase, ASR-Momentenbegrenzung) modulieren das Drehmoment hochdynamisch über Zündwinkelverstellung im Intervall [EngTqCrksftMinFast, EngTqCrksftMaxFast].\n</li></ul>\n</li><li><strong>Aufbau und Abruf von Momentenreserven:</strong>\n<ul class=\"fig-list\"><li>Zur Beschleunigung nachfolgender Drehmomentanforderungen fordert der Powertrain via <code>PtTqResvEng</code> eine Reserve an.\n</li><li>Das EMS öffnet den Luftpfad (Anheben von <code>EngTqCrksftMaxFast</code>), verzögert zeitgleich den Zündwinkel, hält <code>EngTqCrksft</code> konstant und meldet die Spanne als <code>EngTqResvPt</code> zurück.\n</li></ul>\n</li><li><strong>Schutzintervention (<code>Torque intervention</code>):</strong>\n<ul class=\"fig-list\"><li>Meldet die Motorschutzfunktion eine thermische oder mechanische Grenzwertüberschreitung, limitiert <code>EngTqCrksftMaxProtn</code> unmittelbar den zulässigen Momentenbereich und übersteuert alle externen Fahrer- und Powertrain-Sollwerte.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Schnittstellen-Vertrag (API Contract):</strong>\n<ul class=\"fig-list\"><li>Funktionssoftware-Komponenten (SW-Cs) wie Getriebesteuerung (TCM) oder Fahrdynamikregler (ESP) dürfen schnelle Drehmomentanforderungen ausschließlich innerhalb der dynamischen Grenzen <code>EngTqCrksftMinFast</code> und <code>EngTqCrksftMaxFast</code> anfordern.\n</li><li>Anforderungen außerhalb dieses Fensters erfordern Vorlaufzeit für den Füllungsaufbau bzw. führen zu Schnittstellenclipping.\n</li></ul>\n</li><li><strong>Vorzeichenkonvention &amp; Datentypen:</strong>\n<ul class=\"fig-list\"><li>Bezugspunkt ist die Kurbelwelle (Nettoabtrieb). Werte unterhalb des Nullpunkts stellen Schleppmomente dar (Motorbremswirkung).\n</li><li>In der RTE-Konfiguration (<code>AUTOSAR DataType</code>) müssen vorzeichenbehaftete Datentypen (<code>sint16</code> oder <code>float32</code>) mit ausreichender Auflösung und Bereichsabdeckung bis mindestens <code>EngTqCrksftMin</code> konfiguriert werden.\n</li></ul>\n</li><li><strong>Schubabschaltung &amp; Übergänge:</strong>\n<ul class=\"fig-list\"><li>Unterhalb von <code>EngTqCrksftMinWoCutOff</code> erfordert die Momentenreduktion die Deaktivierung von Zylindern (Schubabschaltung / Fuel Cut-Off) bis hin zu <code>EngTqCrksftMin</code>. SW-Cs müssen hierbei NVH- und Ruck-Begrenzungen berücksichtigen.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-a117b53465fb19ed", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Domänenspezifisches Wertebereichs- und Schnittstellen-Mapping-Diagramm (Semantisches Wertebereichsprofil / Range &amp; Boundary Model) für Kurbelwellen-Drehmomentschnittstellen.\n</li><li><strong>Technischer Zweck:</strong> Standardisierung der Drehmoment-Koordination (<em>Torque Coordination</em>) zwischen Motorsteuergerät (Engine Management System, EMS) und aggregierten Antriebsstrang-/Fahrwerk-Steuergeräten (Transmission Control, ESP/ASR).\n</li><li><strong>Funktionale Einordnung:</strong> Definiert die AUTOSAR Sender-Receiver-Schnittstellenelemente (<code>AUTOSAR_EXP_AIPowertrain</code>) bezüglich ihrer physikalischen Wirkpfade (Luftpfad/langsam vs. Zündpfad/schnell), ihrer Begrenzungsebenen (Schleppmoment, Leerlaufbasis, Teillast, thermodynamisches Optimum, Motorschutz) sowie ihrer Einbettung in den Wertebereich des AUTOSAR-Datentyps.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind standardisierte AUTOSAR Application Data Elements (Einheit: Nm, Kurbelwellenreferenz) und deren relationale Ordnung entlang der Drehmomentachse:</p>\n<h5 class=\"fig-section-h5\">Datentypgrenzen &amp; Maximalpotential</h5>\n<ul class=\"fig-list\"><li><strong><code>Upper limit of data type</code> / <code>Lower limit of data type</code>:</strong> Numerische Sättigungsgrenzen des zugrundeliegenden AUTOSAR Implementation Data Types (z. B. vorzeichenbehafteter Festkomma- oder Fließkommatyp).\n</li><li><strong><code>EngTqCrksftMaxOptmCdn</code>:</strong> Maximales Kurbelwellenmoment unter thermodynamischen Idealbedingungen (Referenz-Vollastpotential bei optimalem Zündwinkel, optimalem $\\lambda$, Nenntemperatur).\n</li><li><strong><code>EngTqCrksftMax</code>:</strong> Maximales Kurbelwellenmoment bei maximaler Füllung (Luftmasse) und aktueller Motordrehzahl über den langsamen Pfad.\n</li><li><strong><code>EngTqCrksftMaxProtn</code>:</strong> Dynamische Obergrenze zum Bauteilschutz (Engine Protection Interventionsgrenze; limitiert alle Sollwerte bei thermischer/mechanischer Überlast).\n</li></ul>\n<h5 class=\"fig-section-h5\">Schneller Eingriffspfad &amp; Ist-Zustand (Dynamischer Bereich)</h5>\n<ul class=\"fig-list\"><li><strong><code>EngTqCrksftMaxFast</code>:</strong> Maximal erreichbares Drehmoment über den schnellen Pfad bei aktueller Zylinderfüllung (optimaler Zündwinkel, ungedrosselter Wirkungsgrad). Dient externen Systemen als oberer transienter Stellgrenzwert (<code>Setpoint</code>).\n</li><li><strong><code>EngTqCrksft</code>:</strong> Aktuell an der Kurbelwelle anliegendes Ist-Drehmoment; resultiert aus der aktuellen Zylinderfüllung abzüglich Zündwinkelspätverstellung (<code>spark retard</code>), Gemischadaption ($\\lambda$) und internen Reibverlusten.\n</li><li><strong><code>EngTqCrksftMinFast</code>:</strong> Minimal erreichbares Drehmoment über den schnellen Pfad bei maximaler Zündwinkelspätverstellung (<code>Maximum spark retard</code>) ohne Zylinderausblendung. Dient externen Systemen als unterer transienter Stellgrenzwert (<code>Setpoint</code>).\n</li></ul>\n<h5 class=\"fig-section-h5\">Schleppmoment- und Basispfad (Langsamer Pfad / Schub)</h5>\n<ul class=\"fig-list\"><li><strong><code>EngTqCrksftMinBasc</code>:</strong> Minimales Kurbelwellendrehmoment realisiert über den langsamen Pfad bei minimaler Füllung (geschlossene Drosselklappe/Minimalhub) und Basiszündwinkel (ohne Spätverstellung).\n</li><li><strong><code>EngTqCrksftMinWoCutOff</code>:</strong> Minimales Drehmoment über kombinierten langsamen und schnellen Pfad ohne Schubabschaltung (minimale Füllung + maximale Spätzündung).\n</li><li><strong><code>EngTqCrksftMin</code>:</strong> Absolutes Minimalmoment an der Kurbelwelle unter Berücksichtigung aller innermotorischen Verluste (Reibung, Ladungswechsel, Nebenaggregate; entspricht Schubabschaltung / indiziertes Moment ≈ 0).\n</li><li><strong><code>Indicated torque</code>:</strong> Verbrennungsmoment vor Abzug der innermotorischen Reib- und Ladungswechselverluste (Nullpunktverschiebung gegenüber dem Kurbelwellen-Nettomoment).\n</li></ul>\n<h5 class=\"fig-section-h5\">Momentenreserve-Schnittstellen (<code>Additional interfaces</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>PtTqResvEng</code>:</strong> Drehmomentreserve-Anforderung vom Powertrain/Getriebe an den Motor (Öffnen der Drosselklappe / Vorsteuerung des Füllungspfads).\n</li><li><strong><code>EngTqResvPt</code>:</strong> Rückmeldung des Motors über die aktuell vorgehaltene und schnell aktivierbare Drehmomentreserve an den Powertrain.\n</li></ul>\n<h5 class=\"fig-section-h5\">Mathematische Ordnungshierarchie</h5>\n<p class=\"fig-p\">$$\\text{Lower Limit} \\le \\text{EngTqCrksftMin} &lt; \\text{EngTqCrksftMinWoCutOff} &lt; \\text{EngTqCrksftMinBasc} \\le 0 \\le \\text{EngTqCrksftMinFast} \\le \\text{EngTqCrksft} \\le \\text{EngTqCrksftMaxFast} \\le \\text{EngTqCrksftMax} \\le \\text{EngTqCrksftMaxOptmCdn} \\le \\text{Upper Limit}$$</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Pfadentkopplung (Dual-Path-Architektur):</strong>\n<ul class=\"fig-list\"><li><em>Slow Path (Luftpfad, $\\tau \\approx 100\\dots 300\\,\\text{ms}$):</em> Definiert das Grundfüllungsband zwischen <code>EngTqCrksftMinBasc</code> und <code>EngTqCrksftMax</code>.\n</li><li><em>Fast Path (Zünd-/Einspritzpfad, zylindertakt-synchron, $\\tau \\approx 10\\dots 30\\,\\text{ms}$):</em> Arbeitet innerhalb des Füllungskorridors [<code>EngTqCrksftMinFast</code>, <code>EngTqCrksftMaxFast</code>].\n</li></ul>\n</li><li><strong>Sollwert-Intervention (<code>Setpoint</code>):</strong>\n<ul class=\"fig-list\"><li>Externe Drehmomenteingriffe (z. B. Getriebeeingriff während der Schaltphase, ASR-Momentenbegrenzung) modulieren das Drehmoment hochdynamisch über Zündwinkelverstellung im Intervall [EngTqCrksftMinFast, EngTqCrksftMaxFast].\n</li></ul>\n</li><li><strong>Aufbau und Abruf von Momentenreserven:</strong>\n<ul class=\"fig-list\"><li>Zur Beschleunigung nachfolgender Drehmomentanforderungen fordert der Powertrain via <code>PtTqResvEng</code> eine Reserve an.\n</li><li>Das EMS öffnet den Luftpfad (Anheben von <code>EngTqCrksftMaxFast</code>), verzögert zeitgleich den Zündwinkel, hält <code>EngTqCrksft</code> konstant und meldet die Spanne als <code>EngTqResvPt</code> zurück.\n</li></ul>\n</li><li><strong>Schutzintervention (<code>Torque intervention</code>):</strong>\n<ul class=\"fig-list\"><li>Meldet die Motorschutzfunktion eine thermische oder mechanische Grenzwertüberschreitung, limitiert <code>EngTqCrksftMaxProtn</code> unmittelbar den zulässigen Momentenbereich und übersteuert alle externen Fahrer- und Powertrain-Sollwerte.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Schnittstellen-Vertrag (API Contract):</strong>\n<ul class=\"fig-list\"><li>Funktionssoftware-Komponenten (SW-Cs) wie Getriebesteuerung (TCM) oder Fahrdynamikregler (ESP) dürfen schnelle Drehmomentanforderungen ausschließlich innerhalb der dynamischen Grenzen <code>EngTqCrksftMinFast</code> und <code>EngTqCrksftMaxFast</code> anfordern.\n</li><li>Anforderungen außerhalb dieses Fensters erfordern Vorlaufzeit für den Füllungsaufbau bzw. führen zu Schnittstellenclipping.\n</li></ul>\n</li><li><strong>Vorzeichenkonvention &amp; Datentypen:</strong>\n<ul class=\"fig-list\"><li>Bezugspunkt ist die Kurbelwelle (Nettoabtrieb). Werte unterhalb des Nullpunkts stellen Schleppmomente dar (Motorbremswirkung).\n</li><li>In der RTE-Konfiguration (<code>AUTOSAR DataType</code>) müssen vorzeichenbehaftete Datentypen (<code>sint16</code> oder <code>float32</code>) mit ausreichender Auflösung und Bereichsabdeckung bis mindestens <code>EngTqCrksftMin</code> konfiguriert werden.\n</li></ul>\n</li><li><strong>Schubabschaltung &amp; Übergänge:</strong>\n<ul class=\"fig-list\"><li>Unterhalb von <code>EngTqCrksftMinWoCutOff</code> erfordert die Momentenreduktion die Deaktivierung von Zylindern (Schubabschaltung / Fuel Cut-Off) bis hin zu <code>EngTqCrksftMin</code>. SW-Cs müssen hierbei NVH- und Ruck-Begrenzungen berücksichtigen.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d10c1f87c94957ba", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Domänenspezifisches Wertebereichs- und Schnittstellen-Mapping-Diagramm (Semantisches Wertebereichsprofil / Range &amp; Boundary Model) für Kurbelwellen-Drehmomentschnittstellen.\n</li><li><strong>Technischer Zweck:</strong> Standardisierung der Drehmoment-Koordination (<em>Torque Coordination</em>) zwischen Motorsteuergerät (Engine Management System, EMS) und aggregierten Antriebsstrang-/Fahrwerk-Steuergeräten (Transmission Control, ESP/ASR).\n</li><li><strong>Funktionale Einordnung:</strong> Definiert die AUTOSAR Sender-Receiver-Schnittstellenelemente (<code>AUTOSAR_EXP_AIPowertrain</code>) bezüglich ihrer physikalischen Wirkpfade (Luftpfad/langsam vs. Zündpfad/schnell), ihrer Begrenzungsebenen (Schleppmoment, Leerlaufbasis, Teillast, thermodynamisches Optimum, Motorschutz) sowie ihrer Einbettung in den Wertebereich des AUTOSAR-Datentyps.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind standardisierte AUTOSAR Application Data Elements (Einheit: Nm, Kurbelwellenreferenz) und deren relationale Ordnung entlang der Drehmomentachse:</p>\n<h5 class=\"fig-section-h5\">Datentypgrenzen &amp; Maximalpotential</h5>\n<ul class=\"fig-list\"><li><strong><code>Upper limit of data type</code> / <code>Lower limit of data type</code>:</strong> Numerische Sättigungsgrenzen des zugrundeliegenden AUTOSAR Implementation Data Types (z. B. vorzeichenbehafteter Festkomma- oder Fließkommatyp).\n</li><li><strong><code>EngTqCrksftMaxOptmCdn</code> / <code>EngTqCrksftMaxSpdCur</code>:</strong> Maximales Kurbelwellenmoment unter optimalen Bedingungen (<code>Maximum Engine Torque at Crankshaft at Optimum Conditions</code>) bzw. maximales Kurbelwellenmoment bei aktueller Drehzahl (<code>Maximum Torque at Crankshaft at Current Speed</code>).\n</li><li><strong><code>EngTqCrksftMax</code>:</strong> Maximales Kurbelwellenmoment bei maximaler Füllung (<code>Maximum air mass at current speed</code>) über den langsamen Pfad.\n</li><li><strong><code>EngTqCrksftMaxProtn</code>:</strong> Dynamische Obergrenze zum Bauteilschutz (<code>Torque intervention</code> / <code>Maximum Allowed Torque at Crankshaft for Engine Protection</code>).\n</li></ul>\n<h5 class=\"fig-section-h5\">Eingriffspfade, Sollwerte &amp; Ist-Zustand (Dynamischer Bereich)</h5>\n<ul class=\"fig-list\"><li><strong><code>EngTqCrksftMaxFast</code>:</strong> Maximal erreichbares Drehmoment über den schnellen Pfad bei aktueller Zylinderfüllung (<code>Setpoint</code>-Obergrenze des schnellen Stellbereichs).\n</li><li><strong><code>EngTqCrksft</code>:</strong> An der Kurbelwelle anliegendes Drehmoment (<code>Engine Torque at Crankshaft</code>) basierend auf aktueller Füllung und Drehzahl (<code>Current air mass and speed</code>) sowie aktuellen Stellparametern (<code>Current parameters (spark retard, lambda etc.)</code>).\n</li><li><strong><code>EngTqCrksftMinFast</code>:</strong> Minimal erreichbares Drehmoment über den schnellen Pfad bei maximaler Spätzündung (<code>Maximum spark retard</code>; <code>Setpoint</code>-Untergrenze des schnellen Stellbereichs).\n</li><li><strong><code>PtTqCrksftReqSlow</code>:</strong> Drehmomentanforderung des Antriebsstrangs an den langsamen Pfad (<code>Crankshaft Torque Request to be realized by the Slow Path of Powertrain</code>).\n</li><li><strong><code>PtTqCrksftReqFast</code>:</strong> Drehmomentanforderung des Antriebsstrangs an den schnellen Pfad (<code>Crankshaft Torque Request to be realized by the Fast Path of Powertrain</code>).\n</li></ul>\n<h5 class=\"fig-section-h5\">Schleppmoment- und Basispfad (Langsamer Pfad / Schub)</h5>\n<ul class=\"fig-list\"><li><strong><code>EngTqCrksftMinBasc</code>:</strong> Minimales Kurbelwellendrehmoment realisiert über den langsamen Pfad bei minimaler Füllung (<code>Minimum air mass at current speed</code>) ohne Spätzündung.\n</li><li><strong><code>EngTqCrksftMinWoCutOff</code>:</strong> Minimales Kurbelwellendrehmoment über langsamen und schnellen Pfad ohne Schubabschaltung (<code>Minimum air mass at current speed</code> + <code>Maximum spark retard</code>).\n</li><li><strong><code>EngTqCrksftMin</code>:</strong> Absolutes Minimalmoment an der Kurbelwelle unter Berücksichtigung aller Motorverluste (<code>considering all engine losses</code>).\n</li></ul>\n<h5 class=\"fig-section-h5\">Momentenreserve-Schnittstellen (<code>Additional interfaces</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>PtTqResvEng</code>:</strong> Drehmomentreserve-Anforderung vom Antriebsstrang an den Motor (<code>Torque Reserve Request from Powertrain to Engine</code>).\n</li><li><strong><code>EngTqResvPt</code>:</strong> Drehmomentreserve-Anforderung vom Motor an den Antriebsstrang (<code>Torque Reserve Request from Engine to Powertrain</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Pfadentkopplung (Dual-Path-Architektur):</strong>\n<ul class=\"fig-list\"><li><em>Slow Path (Luftpfad, $\\tau \\approx 100\\dots 300\\,\\text{ms}$):</em> Definiert das Grundfüllungsband zwischen <code>EngTqCrksftMinBasc</code> und <code>EngTqCrksftMax</code>.\n</li><li><em>Fast Path (Zünd-/Einspritzpfad, zylindertakt-synchron, $\\tau \\approx 10\\dots 30\\,\\text{ms}$):</em> Arbeitet innerhalb des Füllungskorridors [<code>EngTqCrksftMinFast</code>, <code>EngTqCrksftMaxFast</code>].\n</li></ul>\n</li><li><strong>Sollwert-Intervention (<code>Setpoint</code>):</strong>\n<ul class=\"fig-list\"><li>Externe Drehmomenteingriffe (z. B. Getriebeeingriff während der Schaltphase, ASR-Momentenbegrenzung) modulieren das Drehmoment hochdynamisch über Zündwinkelverstellung im Intervall [EngTqCrksftMinFast, EngTqCrksftMaxFast].\n</li></ul>\n</li><li><strong>Aufbau und Abruf von Momentenreserven:</strong>\n<ul class=\"fig-list\"><li>Zur Beschleunigung nachfolgender Drehmomentanforderungen fordert der Powertrain via <code>PtTqResvEng</code> eine Reserve an.\n</li><li>Das EMS öffnet den Luftpfad (Anheben von <code>EngTqCrksftMaxFast</code>), verzögert zeitgleich den Zündwinkel, hält <code>EngTqCrksft</code> konstant und meldet die Spanne als <code>EngTqResvPt</code> zurück.\n</li></ul>\n</li><li><strong>Schutzintervention (<code>Torque intervention</code>):</strong>\n<ul class=\"fig-list\"><li>Meldet die Motorschutzfunktion eine thermische oder mechanische Grenzwertüberschreitung, limitiert <code>EngTqCrksftMaxProtn</code> unmittelbar den zulässigen Momentenbereich und übersteuert alle externen Fahrer- und Powertrain-Sollwerte.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Schnittstellen-Vertrag (API Contract):</strong>\n<ul class=\"fig-list\"><li>Funktionssoftware-Komponenten (SW-Cs) wie Getriebesteuerung (TCM) oder Fahrdynamikregler (ESP) dürfen schnelle Drehmomentanforderungen ausschließlich innerhalb der dynamischen Grenzen <code>EngTqCrksftMinFast</code> und <code>EngTqCrksftMaxFast</code> anfordern.\n</li><li>Anforderungen außerhalb dieses Fensters erfordern Vorlaufzeit für den Füllungsaufbau bzw. führen zu Schnittstellenclipping.\n</li></ul>\n</li><li><strong>Vorzeichenkonvention &amp; Datentypen:</strong>\n<ul class=\"fig-list\"><li>Bezugspunkt ist die Kurbelwelle (Nettoabtrieb). Werte unterhalb des Nullpunkts stellen Schleppmomente dar (Motorbremswirkung).\n</li><li>In der RTE-Konfiguration (<code>AUTOSAR DataType</code>) müssen vorzeichenbehaftete Datentypen (<code>sint16</code> oder <code>float32</code>) mit ausreichender Auflösung und Bereichsabdeckung bis mindestens <code>EngTqCrksftMin</code> konfiguriert werden.\n</li></ul>\n</li><li><strong>Schubabschaltung &amp; Übergänge:</strong>\n<ul class=\"fig-list\"><li>Unterhalb von <code>EngTqCrksftMinWoCutOff</code> erfordert die Momentenreduktion die Deaktivierung von Zylindern (Schubabschaltung / Fuel Cut-Off) bis hin zu <code>EngTqCrksftMin</code>. SW-Cs müssen hierbei NVH- und Ruck-Begrenzungen berücksichtigen.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c40c7172f61ceef4", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Domänenspezifisches Wertebereichs- und Schnittstellen-Mapping-Diagramm (Semantisches Wertebereichsprofil / Range &amp; Boundary Model) für Kurbelwellen-Drehmomentschnittstellen.\n</li><li><strong>Technischer Zweck:</strong> Standardisierung der Drehmoment-Koordination (<em>Torque Coordination</em>) zwischen Motorsteuergerät (Engine Management System, EMS) und aggregierten Antriebsstrang-/Fahrwerk-Steuergeräten (Transmission Control, ESP/ASR).\n</li><li><strong>Funktionale Einordnung:</strong> Definiert die AUTOSAR Sender-Receiver-Schnittstellenelemente (<code>AUTOSAR_EXP_AIPowertrain</code>) bezüglich ihrer physikalischen Wirkpfade (Luftpfad/langsam vs. Zündpfad/schnell), ihrer Begrenzungsebenen (Schleppmoment, Leerlaufbasis, Teillast, thermodynamisches Optimum, Motorschutz) sowie ihrer Einbettung in den Wertebereich des AUTOSAR-Datentyps.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind standardisierte AUTOSAR Application Data Elements (Einheit: Nm, Kurbelwellenreferenz) und deren relationale Ordnung entlang der Drehmomentachse:</p>\n<h5 class=\"fig-section-h5\">Datentypgrenzen &amp; Maximalpotential</h5>\n<ul class=\"fig-list\"><li><strong><code>Upper limit of data type</code> / <code>Lower limit of data type</code>:</strong> Numerische Sättigungsgrenzen des zugrundeliegenden AUTOSAR Implementation Data Types (z. B. vorzeichenbehafteter Festkomma- oder Fließkommatyp).\n</li><li><strong><code>EngTqCrksftMaxOptmCdn</code> / <code>EngTqCrksftMaxSpdCur</code>:</strong> Maximales Kurbelwellenmoment unter optimalen Bedingungen (<code>Maximum Engine Torque at Crankshaft at Optimum Conditions</code>) bzw. maximales Kurbelwellenmoment bei aktueller Drehzahl (<code>Maximum Torque at Crankshaft at Current Speed</code>).\n</li><li><strong><code>EngTqCrksftMax</code>:</strong> Maximales Kurbelwellenmoment bei maximaler Füllung (<code>Maximum air mass at current speed</code>) über den langsamen Pfad.\n</li><li><strong><code>EngTqCrksftMaxProtn</code>:</strong> Dynamische Obergrenze zum Bauteilschutz (<code>Torque intervention</code> / <code>Maximum Allowed Torque at Crankshaft for Engine Protection</code>).\n</li></ul>\n<h5 class=\"fig-section-h5\">Eingriffspfade, Sollwerte &amp; Ist-Zustand (Dynamischer Bereich)</h5>\n<ul class=\"fig-list\"><li><strong><code>EngTqCrksftMaxFast</code>:</strong> Maximal erreichbares Drehmoment über den schnellen Pfad bei aktueller Zylinderfüllung (<code>Setpoint</code>-Obergrenze des schnellen Stellbereichs).\n</li><li><strong><code>EngTqCrksft</code>:</strong> An der Kurbelwelle anliegendes Drehmoment (<code>Engine Torque at Crankshaft</code>) basierend auf aktueller Füllung und Drehzahl (<code>Current air mass and speed</code>) sowie aktuellen Stellparametern (<code>Current parameters (spark retard, lambda etc.)</code>).\n</li><li><strong><code>EngTqCrksftMinFast</code>:</strong> Minimal erreichbares Drehmoment über den schnellen Pfad bei maximaler Spätzündung (<code>Maximum spark retard</code>; <code>Setpoint</code>-Untergrenze des schnellen Stellbereichs).\n</li><li><strong><code>PtTqCrksftReqSlow</code>:</strong> Drehmomentanforderung des Antriebsstrangs an den langsamen Pfad (<code>Crankshaft Torque Request to be realized by the Slow Path of Powertrain</code>).\n</li><li><strong><code>PtTqCrksftReqFast</code>:</strong> Drehmomentanforderung des Antriebsstrangs an den schnellen Pfad (<code>Crankshaft Torque Request to be realized by the Fast Path of Powertrain</code>).\n</li></ul>\n<h5 class=\"fig-section-h5\">Schleppmoment- und Basispfad (Langsamer Pfad / Schub)</h5>\n<ul class=\"fig-list\"><li><strong><code>EngTqCrksftMinBasc</code>:</strong> Minimales Kurbelwellendrehmoment realisiert über den langsamen Pfad bei minimaler Füllung (<code>Minimum air mass at current speed</code>) ohne Spätzündung.\n</li><li><strong><code>EngTqCrksftMinWoCutOff</code>:</strong> Minimales Kurbelwellendrehmoment über langsamen und schnellen Pfad ohne Schubabschaltung (<code>Minimum air mass at current speed</code> + <code>Maximum spark retard</code>).\n</li><li><strong><code>EngTqCrksftMin</code>:</strong> Absolutes Minimalmoment an der Kurbelwelle unter Berücksichtigung aller Motorverluste (<code>considering all engine losses</code>).\n</li></ul>\n<h5 class=\"fig-section-h5\">Momentenreserve-Schnittstellen (<code>Additional interfaces</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>PtTqResvEng</code>:</strong> Drehmomentreserve-Anforderung vom Antriebsstrang an den Motor (<code>Torque Reserve Request from Powertrain to Engine</code>).\n</li><li><strong><code>EngTqResvPt</code>:</strong> Drehmomentreserve-Anforderung vom Motor an den Antriebsstrang (<code>Torque Reserve Request from Engine to Powertrain</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Pfadentkopplung (Dual-Path-Architektur):</strong>\n<ul class=\"fig-list\"><li><em>Slow Path (Luftpfad, $\\tau \\approx 100\\dots 300\\,\\text{ms}$):</em> Definiert das Grundfüllungsband zwischen <code>EngTqCrksftMinBasc</code> und <code>EngTqCrksftMax</code>.\n</li><li><em>Fast Path (Zünd-/Einspritzpfad, zylindertakt-synchron, $\\tau \\approx 10\\dots 30\\,\\text{ms}$):</em> Arbeitet innerhalb des Füllungskorridors [<code>EngTqCrksftMinFast</code>, <code>EngTqCrksftMaxFast</code>].\n</li></ul>\n</li><li><strong>Sollwert-Intervention (<code>Setpoint</code>):</strong>\n<ul class=\"fig-list\"><li>Externe Drehmomenteingriffe (z. B. Getriebeeingriff während der Schaltphase, ASR-Momentenbegrenzung) modulieren das Drehmoment hochdynamisch über Zündwinkelverstellung im Intervall [EngTqCrksftMinFast, EngTqCrksftMaxFast].\n</li></ul>\n</li><li><strong>Aufbau und Abruf von Momentenreserven:</strong>\n<ul class=\"fig-list\"><li>Zur Beschleunigung nachfolgender Drehmomentanforderungen fordert der Powertrain via <code>PtTqResvEng</code> eine Reserve an.\n</li><li>Das EMS öffnet den Luftpfad (Anheben von <code>EngTqCrksftMaxFast</code>), verzögert zeitgleich den Zündwinkel, hält <code>EngTqCrksft</code> konstant und meldet die Spanne als <code>EngTqResvPt</code> zurück.\n</li></ul>\n</li><li><strong>Schutzintervention (<code>Torque intervention</code>):</strong>\n<ul class=\"fig-list\"><li>Meldet die Motorschutzfunktion eine thermische oder mechanische Grenzwertüberschreitung, limitiert <code>EngTqCrksftMaxProtn</code> unmittelbar den zulässigen Momentenbereich und übersteuert alle externen Fahrer- und Powertrain-Sollwerte.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Schnittstellen-Vertrag (API Contract):</strong>\n<ul class=\"fig-list\"><li>Funktionssoftware-Komponenten (SW-Cs) wie Getriebesteuerung (TCM) oder Fahrdynamikregler (ESP) dürfen schnelle Drehmomentanforderungen ausschließlich innerhalb der dynamischen Grenzen <code>EngTqCrksftMinFast</code> und <code>EngTqCrksftMaxFast</code> anfordern.\n</li><li>Anforderungen außerhalb dieses Fensters erfordern Vorlaufzeit für den Füllungsaufbau bzw. führen zu Schnittstellenclipping.\n</li></ul>\n</li><li><strong>Vorzeichenkonvention &amp; Datentypen:</strong>\n<ul class=\"fig-list\"><li>Bezugspunkt ist die Kurbelwelle (Nettoabtrieb). Werte unterhalb des Nullpunkts stellen Schleppmomente dar (Motorbremswirkung).\n</li><li>In der RTE-Konfiguration (<code>AUTOSAR DataType</code>) müssen vorzeichenbehaftete Datentypen (<code>sint16</code> oder <code>float32</code>) mit ausreichender Auflösung und Bereichsabdeckung bis mindestens <code>EngTqCrksftMin</code> konfiguriert werden.\n</li></ul>\n</li><li><strong>Schubabschaltung &amp; Übergänge:</strong>\n<ul class=\"fig-list\"><li>Unterhalb von <code>EngTqCrksftMinWoCutOff</code> erfordert die Momentenreduktion die Deaktivierung von Zylindern (Schubabschaltung / Fuel Cut-Off) bis hin zu <code>EngTqCrksftMin</code>. SW-Cs müssen hierbei NVH- und Ruck-Begrenzungen berücksichtigen.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-df778de938dfea43", "to": "FIG-a117b53465fb19ed", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Am linken Rand wurde die Beschriftung des Pfeils für das indizierte Moment von „Indicated torque“ zu „dicated orque“ abgeschnitten (Layout-/Clipping-Artefakt am Bildrand).\n</li></ul>"}, {"from": "FIG-a117b53465fb19ed", "to": "FIG-d10c1f87c94957ba", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>An der oberen gestrichelten Linie wurde die Schnittstellen-Alternative <code>EngTqCrksftMaxSpdCur</code> (mit Untertitel <code>Engine: Maximum Torque at Crankshaft at Current Speed</code>) neben <code>EngTqCrksftMaxOptmCdn</code> ergänzt.\n</li><li>Die Sollwert-Linien (<code>Setpoint</code>) wurden expliziten Schnittstellen zugeordnet: Die obere rote Linie ist als <code>PtTqCrksftReqSlow</code> (<code>Crankshaft Torque Request to be realized by the Slow Path of Powertrain</code>) und die untere rote Linie als <code>PtTqCrksftReqFast</code> (<code>Crankshaft Torque Request to be realized by the Fast Path of Powertrain</code>) benannt.\n</li><li>Die Beschriftung von <code>EngTqCrksft</code> wurde von <code>Actual Engine Torque at Crankshaft</code> zu <code>Engine Torque at Crankshaft</code> verkürzt.\n</li></ul>"}, {"from": "FIG-d10c1f87c94957ba", "to": "FIG-c40c7172f61ceef4", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
